    { auto: true },
  ],
});

watcherTest.describe('File Watcher API', () => {
  watcherTest.beforeEach(async ({ page }) => {
    await connectWebSocket(page);
  });

  // AC: @daemon-server ac-4
  watcherTest(
    'broadcasts files:updates when a YAML file in .kspec is modified',
    async ({ page, daemon }) => {
      // Subscribe to the files:updates topic
      await subscribeTopic(page, 'files:updates');

      // Set up broadcast listener BEFORE modifying the file
      const broadcastPromise = waitForBroadcast(page, 'files:updates');

      // Modify a YAML file directly in the daemon's .kspec directory
      const targetFile = join(daemon.kspecDir, 'kynetic.yaml');
      writeFileSync(
        targetFile,
        `kynetic: "1.0"\n\nproject:\n  name: "E2E Watcher Test Project"\n  version: "0.1.1"\n  status: draft\n  description: Modified by watcher test\n`
      );

      // Wait for the watcher to debounce and broadcast
      const broadcast = await broadcastPromise;

      // AC: @daemon-server ac-4 — file change triggers WebSocket broadcast
      expect(broadcast).toHaveProperty('msg_id');
      expect(typeof broadcast.msg_id).toBe('string');
      expect(broadcast.msg_id.length).toBeGreaterThan(0);

      expect(broadcast.topic).toBe('files:updates');
      expect(broadcast).toHaveProperty('event');
      expect(typeof broadcast.event).toBe('string');

      // Broadcast should include the changed file reference
      expect(broadcast).toHaveProperty('data');
    }
  );

  // AC: @daemon-server ac-4
  watcherTest(
    'modified file change is reflected in subsequent GET request',
    async ({ page, daemon, request }) => {
      // Subscribe to files:updates
      await subscribeTopic(page, 'files:updates');

      // Set up broadcast listener before modification
      const broadcastPromise = waitForBroadcast(page, 'files:updates');

      // Add a task note via HTTP to trigger a file change (API writes to .kspec/project.tasks.yaml)
      const tasksResponse = await request.get(`${DAEMON_HTTP_URL}/api/tasks`);
      const tasksBody = await tasksResponse.json();
      expect(tasksBody.items.length).toBeGreaterThan(0);

      const taskRef = tasksBody.items[0]._ulid;
      const noteResponse = await request.post(`${DAEMON_HTTP_URL}/api/tasks/${taskRef}/note`, {
        data: {
          content: 'Watcher detection E2E test note',
          author: '@test',
        },
      });
      expect(noteResponse.status()).toBe(200);

      // Wait for broadcast — verifies daemon detected the file change
      const broadcast = await broadcastPromise;

      // AC: @daemon-server ac-4 — broadcast received after file change
      expect(broadcast.topic).toBe('files:updates');

      // Verify the data is visible via subsequent GET — confirms state was reparsed
      const tasksAfter = await request.get(`${DAEMON_HTTP_URL}/api/tasks`);
      expect(tasksAfter.status()).toBe(200);
      const tasksBodyAfter = await tasksAfter.json();
      expect(Array.isArray(tasksBodyAfter.items)).toBe(true);
    }
  );

  // AC: @daemon-server ac-5
  watcherTest(
    'rapid successive file changes are debounced into a single broadcast',
    async ({ page, daemon }) => {
      // Subscribe to files:updates
      await subscribeTopic(page, 'files:updates');

      // Track all broadcasts received during the test
      const broadcastCount = await page.evaluate(
        ({ topicName }: { topicName: string }) => {
          return new Promise<number>((resolve) => {
            const ws = (window as unknown as Record<string, WebSocket>).__testWs;
            if (!ws || ws.readyState !== WebSocket.OPEN) {
              resolve(0);
              return;
            }

            let count = 0;
            const original = ws.onmessage;

            ws.onmessage = (event) => {
              try {
                const data = JSON.parse(event.data);
                if (data.topic === topicName && data.msg_id) {
                  count++;
                }
              } catch {
                // ignore
              }
              if (original) original.call(ws, event);
            };

            // Resolve after 1500ms — enough time for debounced events to arrive
            setTimeout(() => {
              ws.onmessage = original;
              resolve(count);
            }, 1500);
          });
        },
        { topicName: 'files:updates' }
      );

      // While the browser is counting, make rapid file changes from Node.js side
      // These must all happen within the 1500ms counting window, before debounce settles
      const targetFile = join(daemon.kspecDir, 'kynetic.yaml');
      const baseContent = `kynetic: "1.0"\n\nproject:\n  name: "Debounce Test"\n  version: "0.1.0"\n  status: draft\n`;

      // Write multiple times rapidly (< 500ms apart each)
      writeFileSync(targetFile, baseContent + '  description: change 1\n');
      await new Promise((r) => setTimeout(r, 100));
      writeFileSync(targetFile, baseContent + '  description: change 2\n');
      await new Promise((r) => setTimeout(r, 100));
      writeFileSync(targetFile, baseContent + '  description: change 3\n');

      // Wait for counting to complete (1500ms from subscription)
      await page.waitForTimeout(1600);

      // Re-evaluate to get the final count
      const finalCount = await page.evaluate(() => {
        return (window as unknown as Record<string, number>).__debounceCount ?? 0;
      });

      // AC: @daemon-server ac-5 — debounce collapses rapid changes into fewer broadcasts
      // We expect either 1 broadcast (perfect debounce) or at most 2 (timing edge case).
      // The debounce window is 500ms; 3 writes at 100ms intervals should produce 1 broadcast.
      // broadcastCount is from the page.evaluate promise which ran concurrently
      expect(broadcastCount).toBeLessThanOrEqual(2);
      // We also expect at least 1 — the watcher did detect a change
      expect(broadcastCount).toBeGreaterThanOrEqual(1);

      // Suppress unused variable warning
      void finalCount;
    }
  );

  // AC: @daemon-server ac-5
  watcherTest(
    'single broadcast received for rapid file modifications (debounce verification)',
    async ({ page, daemon }) => {
      // Subscribe to files:updates
      await subscribeTopic(page, 'files:updates');

      // Write the first change to start the debounce timer
      const targetFile = join(daemon.kspecDir, 'kynetic.yaml');
      const baseContent = `kynetic: "1.0"\n\nproject:\n  name: "Debounce Test 2"\n  version: "0.1.0"\n  status: draft\n`;

      // Make 3 rapid writes all within 300ms — well within 500ms debounce
      writeFileSync(targetFile, baseContent + '  description: rapid 1\n');
      await new Promise((r) => setTimeout(r, 80));
      writeFileSync(targetFile, baseContent + '  description: rapid 2\n');
      await new Promise((r) => setTimeout(r, 80));
      writeFileSync(targetFile, baseContent + '  description: rapid 3\n');

      // Now wait for exactly ONE broadcast (debounce fires after 500ms idle)
      const broadcast = await waitForBroadcast(page, 'files:updates');

      // AC: @daemon-server ac-5 — broadcast is received (debounce allowed event through)
      expect(broadcast.topic).toBe('files:updates');
      expect(broadcast).toHaveProperty('msg_id');

      // Wait another 600ms and verify no additional broadcasts came through
      const secondBroadcastReceived = await page.evaluate(({ topic }: { topic: string }) => {
        return new Promise<boolean>((resolve) => {
          const ws = (window as unknown as Record<string, WebSocket>).__testWs;
          if (!ws || ws.readyState !== WebSocket.OPEN) {
            resolve(false);
            return;
          }

          let received = false;
          const original = ws.onmessage;

          ws.onmessage = (event) => {
            try {
              const data = JSON.parse(event.data);
              if (data.topic === topic && data.msg_id) {
                received = true;
              }
            } catch {
              // ignore
            }
            if (original) original.call(ws, event);
          };

          setTimeout(() => {
            ws.onmessage = original;
            resolve(received);
          }, 600);
        });
      }, { topic: 'files:updates' });

      // AC: @daemon-server ac-5 — no second broadcast within 600ms of the first
      // (confirms rapid writes were merged into one)
      expect(secondBroadcastReceived).toBe(false);
    }
  );

  // AC: @daemon-server ac-6
  watcherTest(
    'YAML parse error does not crash the daemon — broadcasts error event instead',
    async ({ page, daemon, request }) => {
      // Subscribe to both topics
      await subscribeTopic(page, 'files:updates');
      await subscribeTopic(page, 'files:errors');

      // Write invalid YAML to trigger a parse error
      const targetFile = join(daemon.kspecDir, 'kynetic.yaml');
      const invalidYaml = `kynetic: "1.0"\n{ invalid yaml: [unclosed bracket\n  bad: indent:\n`;

      // Set up listener for error broadcast before writing the bad file
      const errorBroadcastPromise = waitForErrorBroadcast(page);

      writeFileSync(targetFile, invalidYaml);

      // Wait for the error broadcast
      const errorBroadcast = await errorBroadcastPromise;

      // AC: @daemon-server ac-6 — error event is broadcast, not a crash
      expect(errorBroadcast.topic).toBe('files:errors');
      expect(errorBroadcast).toHaveProperty('event');
      expect(errorBroadcast.event).toBe('file_error');
      expect(errorBroadcast.data).toHaveProperty('error');
      expect(typeof errorBroadcast.data.error).toBe('string');
      expect(errorBroadcast.data.error.length).toBeGreaterThan(0);

      // Verify daemon is still running and responsive (not crashed)
      const healthResponse = await request.get(`${DAEMON_HTTP_URL}/api/health`);
      expect(healthResponse.status()).toBe(200);
    }
  );

  // AC: @daemon-server ac-6
  watcherTest(
    'daemon recovers after YAML parse error — processes subsequent valid file changes',
    async ({ page, daemon, request }) => {
      // Subscribe to topics
      await subscribeTopic(page, 'files:updates');
      await subscribeTopic(page, 'files:errors');

      const targetFile = join(daemon.kspecDir, 'kynetic.yaml');

      // Step 1: Write invalid YAML — should broadcast error
      const errorPromise = waitForErrorBroadcast(page);
      writeFileSync(targetFile, `kynetic: "1.0"\nbad: [unclosed\n`);
      await errorPromise; // Wait for error broadcast to confirm watcher is active

      // Step 2: Fix the file with valid YAML — should broadcast file_changed
      const recoveryPromise = waitForBroadcast(page, 'files:updates');
      writeFileSync(
        targetFile,
        `kynetic: "1.0"\n\nproject:\n  name: "Recovered Project"\n  version: "0.1.0"\n  status: draft\n  description: Recovered from YAML error\n`
      );
      const recoveryBroadcast = await recoveryPromise;

      // AC: @daemon-server ac-6 — daemon processes valid file after error (not crashed)
      expect(recoveryBroadcast.topic).toBe('files:updates');
      expect(recoveryBroadcast).toHaveProperty('msg_id');

      // Daemon still healthy
      const healthResponse = await request.get(`${DAEMON_HTTP_URL}/api/health`);
      expect(healthResponse.status()).toBe(200);
    }
  );
});

