    writeFileSync(targetFile, base + '  description: rapid write 1\n');
    await new Promise((r) => setTimeout(r, 60));
    writeFileSync(targetFile, base + '  description: rapid write 2\n');
    await new Promise((r) => setTimeout(r, 60));
    writeFileSync(targetFile, base + '  description: rapid write 3\n');

    // Wait for counting window to complete
    const broadcastCount = await countingPromise;

    // AC: @daemon-server ac-5 — debounce collapses rapid writes into fewer broadcasts
    // Ideal: 1 broadcast. Allow up to 2 for timing edge cases (first write debounce may
    // have already fired before the second write; third write triggers a second debounce).
    expect(broadcastCount).toBeGreaterThanOrEqual(1); // At least one change was detected
    expect(broadcastCount).toBeLessThanOrEqual(2); // But not three (proving debounce works)
  });

  // AC: @daemon-server ac-5
  test('single broadcast for rapid writes — no duplicate immediately after debounce', async ({
    page,
    daemon,
  }) => {
    await subscribeTopic(page, 'files:updates');

    const targetFile = join(daemon.kspecDir, 'kynetic.yaml');
    const base = `kynetic: "1.0"\n\nproject:\n  name: "Debounce Verify"\n  version: "0.1.0"\n  status: draft\n`;

    // Make 3 rapid writes within 150ms — all within 500ms debounce window
    writeFileSync(targetFile, base + '  description: write A\n');
    await new Promise((r) => setTimeout(r, 50));
    writeFileSync(targetFile, base + '  description: write B\n');
    await new Promise((r) => setTimeout(r, 50));
    writeFileSync(targetFile, base + '  description: write C\n');

    // The debounce fires 500ms after the last write (write C + 500ms)
    // Wait for the first (and ideally only) broadcast
    const firstBroadcast = await waitForBroadcast(page, 'files:updates');

    // AC: @daemon-server ac-5 — debounce produces a broadcast
    expect(firstBroadcast.topic).toBe('files:updates');
    expect(firstBroadcast).toHaveProperty('msg_id');

    // Verify no second broadcast arrives within 400ms after the first
    // (400ms < 500ms debounce window, so any lingering debounce would have fired)
    const duplicateCount = await countBroadcasts(page, 'files:updates', 400);
    expect(duplicateCount).toBe(0);
  });

  // AC: @daemon-server ac-6
  test('YAML parse error does not crash the daemon — broadcasts error event on files:errors', async ({
    page,
    daemon,
    request,
  }) => {
    await subscribeTopic(page, 'files:updates');
    await subscribeTopic(page, 'files:errors');

    // Write invalid YAML to trigger a parse error
    const targetFile = join(daemon.kspecDir, 'kynetic.yaml');
    const invalidYaml = `kynetic: "1.0"\n{ invalid yaml: [unclosed bracket\n  bad: indent:\n`;

    // Set up error listener before writing the bad file
    const errorBroadcastPromise = waitForErrorBroadcast(page);

    writeFileSync(targetFile, invalidYaml);

    // Wait for the error broadcast
    const errorBroadcast = await errorBroadcastPromise;

    // AC: @daemon-server ac-6 — error event is broadcast with correct structure
    expect(errorBroadcast.topic).toBe('files:errors');
    expect(errorBroadcast.event).toBe('file_error');
    expect(errorBroadcast).toHaveProperty('msg_id');
    expect(errorBroadcast.data).toHaveProperty('error');
    expect(typeof errorBroadcast.data.error).toBe('string');
    expect(errorBroadcast.data.error.length).toBeGreaterThan(0);

    // AC: @daemon-server ac-6 — daemon is still running (did not crash)
    const healthResponse = await request.get(`${DAEMON_HTTP_URL}/api/health`);
    expect(healthResponse.status()).toBe(200);
    const health = await healthResponse.json();
    expect(health.status).toBe('ok');
  });

  // AC: @daemon-server ac-6
  test('daemon recovers after YAML parse error — processes subsequent valid file change', async ({
    page,
    daemon,
    request,
  }) => {
    await subscribeTopic(page, 'files:updates');
    await subscribeTopic(page, 'files:errors');

    const targetFile = join(daemon.kspecDir, 'kynetic.yaml');

    // Step 1: Write invalid YAML — watcher should broadcast error, NOT crash
    const errorPromise = waitForErrorBroadcast(page);
    writeFileSync(targetFile, `kynetic: "1.0"\n{ invalid: [unclosed\n`);
    await errorPromise; // Confirm error was detected and broadcast

    // Step 2: Fix the file with valid YAML — watcher should resume normally
    const recoveryPromise = waitForBroadcast(page, 'files:updates');
    writeFileSync(
      targetFile,
      `kynetic: "1.0"\n\nproject:\n  name: "Recovered Project"\n  version: "0.1.0"\n  status: draft\n  description: Recovered after YAML parse error\n`
    );
    const recoveryBroadcast = await recoveryPromise;

    // AC: @daemon-server ac-6 — daemon processes valid file change after error (not crashed/frozen)
    expect(recoveryBroadcast.topic).toBe('files:updates');
    expect(recoveryBroadcast).toHaveProperty('msg_id');

    // Daemon still healthy after error + recovery
    const healthResponse = await request.get(`${DAEMON_HTTP_URL}/api/health`);
    expect(healthResponse.status()).toBe(200);
  });
});

